R,C=17,19
g=[[0]*C for _ in range(R)]
pts=[(3,4),(8,11),(13,6)]
for r,c in pts:
 # template: top row cols c-2:c+3=5; rows +1,+2,+3 side posts at +-2; center? observed center marker retained
 for cc in range(c-2,c+3):
  if 0<=r-2<R and 0<=cc<C:g[r-2][cc]=5
 for rr in (r-1,r,r+1):
  if 0<=rr<R:
   for cc in (c-2,c+2):
    if 0<=cc<C:g[rr][cc]=2
 # r-1 center 5
 if 0<=r-1<R:g[r-1][c]=5
 # ray row r+2 across width: color2, central span 5 colored 8
 rr=r+2
 if rr<R:
  for cc in range(C):g[rr][cc]=2
  for cc in range(c-2,c+3):
   if 0<=cc<C:g[rr][cc]=8
 # marker center 3
 g[r][c]=3
print('\n'.join(' '.join(map(str,row)) for row in g))

